window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-33be64148eb8c2a9"]={"versions": [{"id": "FIG-33be64148eb8c2a9", "releases": ["R18-10_R4.4.0_R1.5.0", "R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> Zeit- und Intervall-Ablaufdiagramm (Timing Diagram / Abstrahierter Ausführungs-Trace).\n</li><li><strong>Architektur-Kontext:</strong> AUTOSAR Timing Extensions (<code>AUTOSAR_TPS_TimingExtensions</code>, Kap. 4.6 <em>Logical Execution Time</em>, Abschnitt 4.6.2 <em>Relation between LET Intervals</em>).\n</li><li><strong>Funktionaler Zweck:</strong> Visualisierung des deterministischen Ausführungsmodells für ein periodisches logisches Ausführungsintervall (LET), bei dem die Wiederholrate (Period) identisch mit der Intervalllänge ($\\Delta t_{\\text{LET}} = T_{\\text{Period}}$) ist. Dies garantiert lückenlose (gapless), nicht-überlappende (non-overlapping) und jitterfreie Ausführungszyklen für zeitgetriebene Software-Komponenten (SWCs) auf der RTE.\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Metamodell-Entitäten (Timing Extensions):</strong>\n<ul class=\"fig-list\"><li><code>PeriodicEventTriggering</code> («atpIdentity»): Definiert das zyklische Auftreten des Startereignisses mit den Attributen <code>PERIOD</code>, <code>JITTER</code> (= 0) und <code>MINIMUM-INTER-ARRIVAL-TIME</code>.\n</li><li><code>TimingDescriptionEventChain</code> (<code>TD-EVENT-COMPLEX</code>): Definiert das LET-Intervall über die Relation zwischen Startereignis (<code>stimulus</code>: LET-Release) und Endereignis (<code>response</code>: LET-Publish).\n</li><li><code>EventOccurrenceKind</code>: Markiert Release- und Expiry-Zeitpunkte der logischen Ausführung.\n</li></ul>\n</li><li><strong>Dargestellte Elemente:</strong>\n<ul class=\"fig-list\"><li><strong>LET Interval 1 (blau hervorgehoben):</strong> Einzelne logische Ausführungseinheit eines Runnables bzw. einer Runnable-Kette.\n</li><li><strong>Folgeintervalle (grau, <code>1</code>):</strong> Zyklische Folgeinstanzen desselben LET-Intervalls über die Zeitachse.\n</li><li><strong>Period:</strong> Dauer zwischen zwei aufeinanderfolgenden Release-Events.\n</li><li><strong>Kardinalität/Beziehung:</strong> 1:1-Abbildung zwischen Intervalllänge und Periodendauer (LET Interval = Period); keine Phasengaps (Gap = 0), kein Überlappungsgrad (Overlap = 0).\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>LET Interval Start / Release Point (t = k · T):</strong>\n<ul class=\"fig-list\"><li>Trigger durch OS-Timer / RTE-Scheduler.\n</li><li>Lese-Semantik (<em>Read at Start</em>): Das Runnable liest Eingangsdaten atomar aus dedizierten Schattenpuffern (Shadow Buffers). Änderungen an Ports während des Intervalls bleiben für das Runnable unsichtbar.\n</li></ul>\n</li><li><strong>Physische Ausführung (t ∈ ]k · T, (k+1) · T[):</strong>\n<ul class=\"fig-list\"><li>Die physische Task-Ausführung erfolgt asynchron, unterbrechbar (preemptiv) oder parallel (Multicore).\n</li><li>Die Beendigung der physischen Berechnung muss strikt vor dem Intervallende erfolgen (WCET ≤ LET). Der konkrete physische Endzeitpunkt hat keinen Einfluss auf den Datenfluss.\n</li></ul>\n</li><li><strong>LET Interval End / Publish Point (t = (k+1) · T):</strong>\n<ul class=\"fig-list\"><li>Schreib-Semantik (<em>Write at End</em>): Ausgangsdaten werden exakt an der Intervallgrenze in globale/nachgelagerte Puffer committet und für Konsumenten sichtbar.\n</li></ul>\n</li><li><strong>Zyklischer Übergang (t = (k+1) · T):</strong>\n<ul class=\"fig-list\"><li>Zeitgleicher Abschluss von Intervall k und Start von Intervall k+1. Datenübergabe zwischen aufeinanderfolgenden Instanzen erfolgt deterministisch mit exakt einer Periode Verzögerung (z^-1).\n</li></ul>\n</li></ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>RTE-Pufferstrategie &amp; Speichereffizienz:</strong>\n<ul class=\"fig-list\"><li>Da Period = LET Interval gilt, entfällt mehrfache Parallelpufferung für überlappende Instanzen. Ein einfaches Ping-Pong- oder Double-Buffering reicht für die RTE-Generierung aus.\n</li></ul>\n</li><li><strong>Scheduling- &amp; WCET-Garantien:</strong>\n<ul class=\"fig-list\"><li>System-Integratoren müssen sicherstellen, dass die Worst-Case Execution Time inkl. Blocking- und Preemption-Zeiten kleiner als das definierte LET-Intervall ist ($\\text{WCRT} &lt; \\Delta t_{\\text{LET}}$).\n</li><li>Ein Überschreiten des Intervalls führt zu einem <em>LET Deadline Miss</em>, der zur Laufzeit über RTE/OS-Überwachungsmechanismen (z. B. Watchdog Manager / <code>WdgM</code>) detektiert und an das <code>Dem</code> gemeldet werden muss.\n</li></ul>\n</li><li><strong>ARXML-Konfigurationskonsistenz:</strong>\n<ul class=\"fig-list\"><li><code>PeriodicEventTriggering.period</code> des Release-Events muss exakt dem Timing-Constraint der Event-Chain für das LET-Intervall entsprechen. Ein deterministischer Ablauf verlangt <code>JITTER = 0</code>.\n</li></ul>\n</li><li><strong>Deterministischer API-Vertrag:</strong>\n<ul class=\"fig-list\"><li>Applikationsentwickler dürfen keine Annahmen über Zwischenstände von R-Ports treffen; Daten sind innerhalb des Runnables während des gesamten Intervalls zeitlich invariant.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-2270544ba0851794", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> Zeit- und Intervall-Ablaufdiagramm (Timing Diagram / Abstrahierter Ausführungs-Trace).\n</li><li><strong>Architektur-Kontext:</strong> AUTOSAR Timing Extensions (<code>AUTOSAR_TPS_TimingExtensions</code>, Kap. 4.6 <em>Logical Execution Time</em>, Abschnitt 4.6.2 <em>Relation between LET Intervals</em>).\n</li><li><strong>Funktionaler Zweck:</strong> Visualisierung des deterministischen Ausführungsmodells für ein periodisches logisches Ausführungsintervall (LET), bei dem die Wiederholrate (Period) identisch mit der Intervalllänge ($\\Delta t_{\\text{LET}} = T_{\\text{Period}}$) ist. Dies garantiert lückenlose (gapless), nicht-überlappende (non-overlapping) und jitterfreie Ausführungszyklen für zeitgetriebene Software-Komponenten (SWCs) auf der RTE.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Metamodell-Entitäten (Timing Extensions):</strong>\n<ul class=\"fig-list\"><li><code>PeriodicEventTriggering</code> («atpIdentity»): Definiert das zyklische Auftreten des Startereignisses mit den Attributen <code>PERIOD</code>, <code>JITTER</code> (= 0) und <code>MINIMUM-INTER-ARRIVAL-TIME</code>.\n</li><li><code>TimingDescriptionEventChain</code> (<code>TD-EVENT-COMPLEX</code>): Definiert das LET-Intervall über die Relation zwischen Startereignis (<code>stimulus</code>: LET-Release) und Endereignis (<code>response</code>: LET-Publish).\n</li><li><code>EventOccurrenceKind</code>: Markiert Release- und Expiry-Zeitpunkte der logischen Ausführung.\n</li></ul>\n</li><li><strong>Dargestellte Elemente:</strong>\n<ul class=\"fig-list\"><li><strong>LET Interval 1 (blau hervorgehoben):</strong> Einzelne logische Ausführungseinheit eines Runnables bzw. einer Runnable-Kette.\n</li><li><strong>Folgeintervalle (grau, <code>1</code>):</strong> Zyklische Folgeinstanzen desselben LET-Intervalls über die Zeitachse.\n</li><li><strong>Period:</strong> Dauer zwischen zwei aufeinanderfolgenden Release-Events.\n</li><li><strong>Kardinalität/Beziehung:</strong> 1:1-Abbildung zwischen Intervalllänge und Periodendauer (LET Interval = Period); keine Phasengaps (Gap = 0), kein Überlappungsgrad (Overlap = 0).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>LET Interval Start / Release Point (t = k · T):</strong>\n<ul class=\"fig-list\"><li>Trigger durch OS-Timer / RTE-Scheduler.\n</li><li>Lese-Semantik (<em>Read at Start</em>): Das Runnable liest Eingangsdaten atomar aus dedizierten Schattenpuffern (Shadow Buffers). Änderungen an Ports während des Intervalls bleiben für das Runnable unsichtbar.\n</li></ul>\n</li><li><strong>Physische Ausführung (t ∈ ]k · T, (k+1) · T[):</strong>\n<ul class=\"fig-list\"><li>Die physische Task-Ausführung erfolgt asynchron, unterbrechbar (preemptiv) oder parallel (Multicore).\n</li><li>Die Beendigung der physischen Berechnung muss strikt vor dem Intervallende erfolgen (WCET ≤ LET). Der konkrete physische Endzeitpunkt hat keinen Einfluss auf den Datenfluss.\n</li></ul>\n</li><li><strong>LET Interval End / Publish Point (t = (k+1) · T):</strong>\n<ul class=\"fig-list\"><li>Schreib-Semantik (<em>Write at End</em>): Ausgangsdaten werden exakt an der Intervallgrenze in globale/nachgelagerte Puffer committet und für Konsumenten sichtbar.\n</li></ul>\n</li><li><strong>Zyklischer Übergang (t = (k+1) · T):</strong>\n<ul class=\"fig-list\"><li>Zeitgleicher Abschluss von Intervall k und Start von Intervall k+1. Datenübergabe zwischen aufeinanderfolgenden Instanzen erfolgt deterministisch mit exakt einer Periode Verzögerung (z^-1).\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>RTE-Pufferstrategie &amp; Speichereffizienz:</strong>\n<ul class=\"fig-list\"><li>Da Period = LET Interval gilt, entfällt mehrfache Parallelpufferung für überlappende Instanzen. Ein einfaches Ping-Pong- oder Double-Buffering reicht für die RTE-Generierung aus.\n</li></ul>\n</li><li><strong>Scheduling- &amp; WCET-Garantien:</strong>\n<ul class=\"fig-list\"><li>System-Integratoren müssen sicherstellen, dass die Worst-Case Execution Time inkl. Blocking- und Preemption-Zeiten kleiner als das definierte LET-Intervall ist ($\\text{WCRT} &lt; \\Delta t_{\\text{LET}}$).\n</li><li>Ein Überschreiten des Intervalls führt zu einem <em>LET Deadline Miss</em>, der zur Laufzeit über RTE/OS-Überwachungsmechanismen (z. B. Watchdog Manager / <code>WdgM</code>) detektiert und an das <code>Dem</code> gemeldet werden muss.\n</li></ul>\n</li><li><strong>ARXML-Konfigurationskonsistenz:</strong>\n<ul class=\"fig-list\"><li><code>PeriodicEventTriggering.period</code> des Release-Events muss exakt dem Timing-Constraint der Event-Chain für das LET-Intervall entsprechen. Ein deterministischer Ablauf verlangt <code>JITTER = 0</code>.\n</li></ul>\n</li><li><strong>Deterministischer API-Vertrag:</strong>\n<ul class=\"fig-list\"><li>Applikationsentwickler dürfen keine Annahmen über Zwischenstände von R-Ports treffen; Daten sind innerhalb des Runnables während des gesamten Intervalls zeitlich invariant.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-d9aa53ed676516b0", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> Zeit- und Intervall-Ablaufdiagramm (Timing Diagram / Abstrahierter Ausführungs-Trace).\n</li><li><strong>Architektur-Kontext:</strong> AUTOSAR Timing Extensions (<code>AUTOSAR_TPS_TimingExtensions</code>, Kap. 4.6 <em>Logical Execution Time</em>, Abschnitt 4.6.2 <em>Relation between LET Intervals</em>).\n</li><li><strong>Funktionaler Zweck:</strong> Visualisierung des deterministischen Ausführungsmodells für ein periodisches logisches Ausführungsintervall (LET), bei dem die Wiederholrate (Period) identisch mit der Intervalllänge ($\\Delta t_{\\text{LET}} = T_{\\text{Period}}$) ist. Dies garantiert lückenlose (gapless), nicht-überlappende (non-overlapping) und jitterfreie Ausführungszyklen für zeitgetriebene Software-Komponenten (SWCs) auf der RTE.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Metamodell-Entitäten (Timing Extensions):</strong>\n<ul class=\"fig-list\"><li><code>PeriodicEventTriggering</code> («atpIdentity»): Definiert das zyklische Auftreten des Startereignisses mit den Attributen <code>PERIOD</code>, <code>JITTER</code> (= 0) und <code>MINIMUM-INTER-ARRIVAL-TIME</code>.\n</li><li><code>TimingDescriptionEventChain</code> (<code>TD-EVENT-COMPLEX</code>): Definiert das LET-Intervall über die Relation zwischen Startereignis (<code>stimulus</code>: LET-Release) und Endereignis (<code>response</code>: LET-Publish).\n</li><li><code>EventOccurrenceKind</code>: Markiert Release- und Expiry-Zeitpunkte der logischen Ausführung.\n</li></ul>\n</li><li><strong>Dargestellte Elemente:</strong>\n<ul class=\"fig-list\"><li><strong>LET Interval 1 (blau hervorgehoben):</strong> Einzelne logische Ausführungseinheit eines Runnables bzw. einer Runnable-Kette.\n</li><li><strong>Folgeintervalle (grau, <code>1</code>):</strong> Zyklische Folgeinstanzen desselben LET-Intervalls über die Zeitachse.\n</li><li><strong>Period:</strong> Dauer zwischen zwei aufeinanderfolgenden Release-Events.\n</li><li><strong>Kardinalität/Beziehung:</strong> 1:1-Abbildung zwischen Intervalllänge und Periodendauer (LET Interval = Period); keine Phasengaps (Gap = 0), kein Überlappungsgrad (Overlap = 0).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>LET Interval Start / Release Point (t = k · T):</strong>\n<ul class=\"fig-list\"><li>Trigger durch OS-Timer / RTE-Scheduler.\n</li><li>Lese-Semantik (<em>Read at Start</em>): Das Runnable liest Eingangsdaten atomar aus dedizierten Schattenpuffern (Shadow Buffers). Änderungen an Ports während des Intervalls bleiben für das Runnable unsichtbar.\n</li></ul>\n</li><li><strong>Physische Ausführung (t ∈ ]k · T, (k+1) · T[):</strong>\n<ul class=\"fig-list\"><li>Die physische Task-Ausführung erfolgt asynchron, unterbrechbar (preemptiv) oder parallel (Multicore).\n</li><li>Die Beendigung der physischen Berechnung muss strikt vor dem Intervallende erfolgen (WCET ≤ LET). Der konkrete physische Endzeitpunkt hat keinen Einfluss auf den Datenfluss.\n</li></ul>\n</li><li><strong>LET Interval End / Publish Point (t = (k+1) · T):</strong>\n<ul class=\"fig-list\"><li>Schreib-Semantik (<em>Write at End</em>): Ausgangsdaten werden exakt an der Intervallgrenze in globale/nachgelagerte Puffer committet und für Konsumenten sichtbar.\n</li></ul>\n</li><li><strong>Zyklischer Übergang (t = (k+1) · T):</strong>\n<ul class=\"fig-list\"><li>Zeitgleicher Abschluss von Intervall k und Start von Intervall k+1. Datenübergabe zwischen aufeinanderfolgenden Instanzen erfolgt deterministisch mit exakt einer Periode Verzögerung (z^-1).\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>RTE-Pufferstrategie &amp; Speichereffizienz:</strong>\n<ul class=\"fig-list\"><li>Da Period = LET Interval gilt, entfällt mehrfache Parallelpufferung für überlappende Instanzen. Ein einfaches Ping-Pong- oder Double-Buffering reicht für die RTE-Generierung aus.\n</li></ul>\n</li><li><strong>Scheduling- &amp; WCET-Garantien:</strong>\n<ul class=\"fig-list\"><li>System-Integratoren müssen sicherstellen, dass die Worst-Case Execution Time inkl. Blocking- und Preemption-Zeiten kleiner als das definierte LET-Intervall ist ($\\text{WCRT} &lt; \\Delta t_{\\text{LET}}$).\n</li><li>Ein Überschreiten des Intervalls führt zu einem <em>LET Deadline Miss</em>, der zur Laufzeit über RTE/OS-Überwachungsmechanismen (z. B. Watchdog Manager / <code>WdgM</code>) detektiert und an das <code>Dem</code> gemeldet werden muss.\n</li></ul>\n</li><li><strong>ARXML-Konfigurationskonsistenz:</strong>\n<ul class=\"fig-list\"><li><code>PeriodicEventTriggering.period</code> des Release-Events muss exakt dem Timing-Constraint der Event-Chain für das LET-Intervall entsprechen. Ein deterministischer Ablauf verlangt <code>JITTER = 0</code>.\n</li></ul>\n</li><li><strong>Deterministischer API-Vertrag:</strong>\n<ul class=\"fig-list\"><li>Applikationsentwickler dürfen keine Annahmen über Zwischenstände von R-Ports treffen; Daten sind innerhalb des Runnables während des gesamten Intervalls zeitlich invariant.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-d7d95b1c243bdab1", "releases": ["R23-11", "R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> Zeit- und Intervall-Ablaufdiagramm (Timing Diagram / Abstrahierter Ausführungs-Trace).\n</li><li><strong>Architektur-Kontext:</strong> AUTOSAR Timing Extensions (<code>AUTOSAR_TPS_TimingExtensions</code>, Kap. 4.6 <em>Logical Execution Time</em>, Abschnitt 4.6.2 <em>Relation between LET Intervals</em>).\n</li><li><strong>Funktionaler Zweck:</strong> Visualisierung des deterministischen Ausführungsmodells für ein periodisches logisches Ausführungsintervall (LET), bei dem die Wiederholrate (Period) identisch mit der Intervalllänge ($\\Delta t_{\\text{LET}} = T_{\\text{Period}}$) ist. Dies garantiert lückenlose (gapless), nicht-überlappende (non-overlapping) und jitterfreie Ausführungszyklen für zeitgetriebene Software-Komponenten (SWCs) auf der RTE.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Metamodell-Entitäten (Timing Extensions):</strong>\n<ul class=\"fig-list\"><li><code>PeriodicEventTriggering</code> («atpIdentity»): Definiert das zyklische Auftreten des Startereignisses mit den Attributen <code>PERIOD</code>, <code>JITTER</code> (= 0) und <code>MINIMUM-INTER-ARRIVAL-TIME</code>.\n</li><li><code>TimingDescriptionEventChain</code> (<code>TD-EVENT-COMPLEX</code>): Definiert das LET-Intervall über die Relation zwischen Startereignis (<code>stimulus</code>: LET-Release) und Endereignis (<code>response</code>: LET-Publish).\n</li><li><code>EventOccurrenceKind</code>: Markiert Release- und Expiry-Zeitpunkte der logischen Ausführung.\n</li></ul>\n</li><li><strong>Dargestellte Elemente:</strong>\n<ul class=\"fig-list\"><li><strong>LET Interval 1 (blau hervorgehoben):</strong> Einzelne logische Ausführungseinheit eines Runnables bzw. einer Runnable-Kette.\n</li><li><strong>Folgeintervalle (grau, <code>1</code>):</strong> Zyklische Folgeinstanzen desselben LET-Intervalls über die Zeitachse.\n</li><li><strong>Period:</strong> Dauer zwischen zwei aufeinanderfolgenden Release-Events.\n</li><li><strong>Kardinalität/Beziehung:</strong> 1:1-Abbildung zwischen Intervalllänge und Periodendauer (LET Interval = Period); keine Phasengaps (Gap = 0), kein Überlappungsgrad (Overlap = 0).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>LET Interval Start / Release Point (t = k · T):</strong>\n<ul class=\"fig-list\"><li>Trigger durch OS-Timer / RTE-Scheduler.\n</li><li>Lese-Semantik (<em>Read at Start</em>): Das Runnable liest Eingangsdaten atomar aus dedizierten Schattenpuffern (Shadow Buffers). Änderungen an Ports während des Intervalls bleiben für das Runnable unsichtbar.\n</li></ul>\n</li><li><strong>Physische Ausführung (t ∈ ]k · T, (k+1) · T[):</strong>\n<ul class=\"fig-list\"><li>Die physische Task-Ausführung erfolgt asynchron, unterbrechbar (preemptiv) oder parallel (Multicore).\n</li><li>Die Beendigung der physischen Berechnung muss strikt vor dem Intervallende erfolgen (WCET ≤ LET). Der konkrete physische Endzeitpunkt hat keinen Einfluss auf den Datenfluss.\n</li></ul>\n</li><li><strong>LET Interval End / Publish Point (t = (k+1) · T):</strong>\n<ul class=\"fig-list\"><li>Schreib-Semantik (<em>Write at End</em>): Ausgangsdaten werden exakt an der Intervallgrenze in globale/nachgelagerte Puffer committet und für Konsumenten sichtbar.\n</li></ul>\n</li><li><strong>Zyklischer Übergang (t = (k+1) · T):</strong>\n<ul class=\"fig-list\"><li>Zeitgleicher Abschluss von Intervall k und Start von Intervall k+1. Datenübergabe zwischen aufeinanderfolgenden Instanzen erfolgt deterministisch mit exakt einer Periode Verzögerung (z^-1).\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>RTE-Pufferstrategie &amp; Speichereffizienz:</strong>\n<ul class=\"fig-list\"><li>Da Period = LET Interval gilt, entfällt mehrfache Parallelpufferung für überlappende Instanzen. Ein einfaches Ping-Pong- oder Double-Buffering reicht für die RTE-Generierung aus.\n</li></ul>\n</li><li><strong>Scheduling- &amp; WCET-Garantien:</strong>\n<ul class=\"fig-list\"><li>System-Integratoren müssen sicherstellen, dass die Worst-Case Execution Time inkl. Blocking- und Preemption-Zeiten kleiner als das definierte LET-Intervall ist ($\\text{WCRT} &lt; \\Delta t_{\\text{LET}}$).\n</li><li>Ein Überschreiten des Intervalls führt zu einem <em>LET Deadline Miss</em>, der zur Laufzeit über RTE/OS-Überwachungsmechanismen (z. B. Watchdog Manager / <code>WdgM</code>) detektiert und an das <code>Dem</code> gemeldet werden muss.\n</li></ul>\n</li><li><strong>ARXML-Konfigurationskonsistenz:</strong>\n<ul class=\"fig-list\"><li><code>PeriodicEventTriggering.period</code> des Release-Events muss exakt dem Timing-Constraint der Event-Chain für das LET-Intervall entsprechen. Ein deterministischer Ablauf verlangt <code>JITTER = 0</code>.\n</li></ul>\n</li><li><strong>Deterministischer API-Vertrag:</strong>\n<ul class=\"fig-list\"><li>Applikationsentwickler dürfen keine Annahmen über Zwischenstände von R-Ports treffen; Daten sind innerhalb des Runnables während des gesamten Intervalls zeitlich invariant.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-62dd1492d471aeae", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> Zeit- und Intervall-Ablaufdiagramm (Timing Diagram / Abstrahierter Ausführungs-Trace).\n</li><li><strong>Architektur-Kontext:</strong> AUTOSAR Timing Extensions (<code>AUTOSAR_TPS_TimingExtensions</code>, Kap. 4.6 <em>Logical Execution Time</em>, Abschnitt 4.6.2 <em>Relation between LET Intervals</em>).\n</li><li><strong>Funktionaler Zweck:</strong> Visualisierung des deterministischen Ausführungsmodells für ein periodisches logisches Ausführungsintervall (LET), bei dem die Wiederholrate (Period) identisch mit der Intervalllänge ($\\Delta t_{\\text{LET}} = T_{\\text{Period}}$) ist. Dies garantiert lückenlose (gapless), nicht-überlappende (non-overlapping) und jitterfreie Ausführungszyklen für zeitgetriebene Software-Komponenten (SWCs) auf der RTE.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Metamodell-Entitäten (Timing Extensions):</strong>\n<ul class=\"fig-list\"><li><code>PeriodicEventTriggering</code> («atpIdentity»): Definiert das zyklische Auftreten des Startereignisses mit den Attributen <code>PERIOD</code>, <code>JITTER</code> (= 0) und <code>MINIMUM-INTER-ARRIVAL-TIME</code>.\n</li><li><code>TimingDescriptionEventChain</code> (<code>TD-EVENT-COMPLEX</code>): Definiert das LET-Intervall über die Relation zwischen Startereignis (<code>stimulus</code>: LET-Release) und Endereignis (<code>response</code>: LET-Publish).\n</li><li><code>EventOccurrenceKind</code>: Markiert Release- und Expiry-Zeitpunkte der logischen Ausführung.\n</li></ul>\n</li><li><strong>Dargestellte Elemente:</strong>\n<ul class=\"fig-list\"><li><strong>LET Interval 1 (blau hervorgehoben):</strong> Einzelne logische Ausführungseinheit eines Runnables bzw. einer Runnable-Kette.\n</li><li><strong>Folgeintervalle (grau, <code>1</code>):</strong> Zyklische Folgeinstanzen desselben LET-Intervalls über die Zeitachse.\n</li><li><strong>Period:</strong> Dauer zwischen zwei aufeinanderfolgenden Release-Events.\n</li><li><strong>Kardinalität/Beziehung:</strong> 1:1-Abbildung zwischen Intervalllänge und Periodendauer (LET Interval = Period); keine Phasengaps (Gap = 0), kein Überlappungsgrad (Overlap = 0).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>LET Interval Start / Release Point (t = k · T):</strong>\n<ul class=\"fig-list\"><li>Trigger durch OS-Timer / RTE-Scheduler.\n</li><li>Lese-Semantik (<em>Read at Start</em>): Das Runnable liest Eingangsdaten atomar aus dedizierten Schattenpuffern (Shadow Buffers). Änderungen an Ports während des Intervalls bleiben für das Runnable unsichtbar.\n</li></ul>\n</li><li><strong>Physische Ausführung (t ∈ ]k · T, (k+1) · T[):</strong>\n<ul class=\"fig-list\"><li>Die physische Task-Ausführung erfolgt asynchron, unterbrechbar (preemptiv) oder parallel (Multicore).\n</li><li>Die Beendigung der physischen Berechnung muss strikt vor dem Intervallende erfolgen (WCET ≤ LET). Der konkrete physische Endzeitpunkt hat keinen Einfluss auf den Datenfluss.\n</li></ul>\n</li><li><strong>LET Interval End / Publish Point (t = (k+1) · T):</strong>\n<ul class=\"fig-list\"><li>Schreib-Semantik (<em>Write at End</em>): Ausgangsdaten werden exakt an der Intervallgrenze in globale/nachgelagerte Puffer committet und für Konsumenten sichtbar.\n</li></ul>\n</li><li><strong>Zyklischer Übergang (t = (k+1) · T):</strong>\n<ul class=\"fig-list\"><li>Zeitgleicher Abschluss von Intervall k und Start von Intervall k+1. Datenübergabe zwischen aufeinanderfolgenden Instanzen erfolgt deterministisch mit exakt einer Periode Verzögerung (z^-1).\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>RTE-Pufferstrategie &amp; Speichereffizienz:</strong>\n<ul class=\"fig-list\"><li>Da Period = LET Interval gilt, entfällt mehrfache Parallelpufferung für überlappende Instanzen. Ein einfaches Ping-Pong- oder Double-Buffering reicht für die RTE-Generierung aus.\n</li></ul>\n</li><li><strong>Scheduling- &amp; WCET-Garantien:</strong>\n<ul class=\"fig-list\"><li>System-Integratoren müssen sicherstellen, dass die Worst-Case Execution Time inkl. Blocking- und Preemption-Zeiten kleiner als das definierte LET-Intervall ist ($\\text{WCRT} &lt; \\Delta t_{\\text{LET}}$).\n</li><li>Ein Überschreiten des Intervalls führt zu einem <em>LET Deadline Miss</em>, der zur Laufzeit über RTE/OS-Überwachungsmechanismen (z. B. Watchdog Manager / <code>WdgM</code>) detektiert und an das <code>Dem</code> gemeldet werden muss.\n</li></ul>\n</li><li><strong>ARXML-Konfigurationskonsistenz:</strong>\n<ul class=\"fig-list\"><li><code>PeriodicEventTriggering.period</code> des Release-Events muss exakt dem Timing-Constraint der Event-Chain für das LET-Intervall entsprechen. Ein deterministischer Ablauf verlangt <code>JITTER = 0</code>.\n</li></ul>\n</li><li><strong>Deterministischer API-Vertrag:</strong>\n<ul class=\"fig-list\"><li>Applikationsentwickler dürfen keine Annahmen über Zwischenstände von R-Ports treffen; Daten sind innerhalb des Runnables während des gesamten Intervalls zeitlich invariant.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-33be64148eb8c2a9", "to": "FIG-2270544ba0851794", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-2270544ba0851794", "to": "FIG-33be64148eb8c2a9", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-33be64148eb8c2a9", "to": "FIG-d9aa53ed676516b0", "fr": "R20-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-d9aa53ed676516b0", "to": "FIG-d7d95b1c243bdab1", "fr": "R22-11", "tr": "R23-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-d7d95b1c243bdab1", "to": "FIG-62dd1492d471aeae", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
